def national_parks_findParks(stateCode=None, q=None, limit=10, start=0, activities=None):
    import json, os
    db = json.load(open(os.path.join(_DB, 'nps.json'), encoding='utf-8'))
    out = []
    for p in db['parks'].values():
        if stateCode and stateCode.upper() not in p['states'].split(','):
            continue
        if q and q.lower() not in (p['fullName'] + ' ' + p['description']).lower():
            continue
        if activities:
            want = [a.strip().lower() for a in activities.split(',')]
            if not (set(want) & set(p['activities'])):
                continue
        out.append(p)
    s = int(start or 0)
    return {'total': len(out), 'data': out[s: s + int(limit)]}

