def national_parks_getParkDetails(parkCode):
    import json, os
    db = json.load(open(os.path.join(_DB, 'nps.json'), encoding='utf-8'))
    p = db['parks'].get(parkCode)
    return p or {'error': 'park ' + str(parkCode) + ' not found'}

