def national_parks_getAlerts(parkCode=None, limit=10, start=0, q=None, dateStart=None, dateEnd=None):
    import json, os
    db = json.load(open(os.path.join(_DB, 'nps.json'), encoding='utf-8'))
    coll = db['alerts']
    items = []
    if parkCode:
        items = list(coll.get(parkCode, []))
    else:
        for v in coll.values():
            items.extend(v)
    if q:
        ql = q.lower()
        items = [i for i in items if ql in json.dumps(i).lower()]
    s = int(start or 0)
    return {'total': len(items), 'data': items[s: s + int(limit)]}

